// The following is equivalent to
//assert not constraint referencesnegativeMass { ... }
assertnotnegativeMass {
:>> mass = computedMass;
}
}
partalienObject {
attributeantiMass : MassValue;
// The following is equivalent to
//assert constraint referencesnegativeMass { ... }
